CREATE UNIQUE INDEX bookings_active_participant_occurrence ON app.bookings USING btree (trial_occurrence_id, participant_id) WHERE status <> 'cancelled';
CREATE UNIQUE INDEX conversations_resume_token_hash ON app.conversations USING btree (resume_token_hash) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX conversations_school_wa_id_hash ON app.conversations USING btree (school_id, wa_id_hash) WHERE wa_id_hash IS NOT NULL AND ended_at IS NULL;
CREATE INDEX email_deliveries_due_idx ON app.email_deliveries USING btree (state, next_attempt_at);
CREATE INDEX funnel_events_school_created_idx ON app.funnel_events USING btree (school_id, created_at);
CREATE UNIQUE INDEX schools_whatsapp_phone_number_id_unique ON app.schools USING btree (whatsapp_phone_number_id) WHERE whatsapp_phone_number_id IS NOT NULL;
CREATE UNIQUE INDEX whatsapp_booking_intents_active_pending ON app.whatsapp_booking_intents USING btree (conversation_id) WHERE state = 'pending';
CREATE INDEX whatsapp_deliveries_due_idx ON app.whatsapp_deliveries USING btree (state, next_attempt_at);
CREATE INDEX whatsapp_jobs_due_idx ON app.whatsapp_jobs USING btree (state, next_attempt_at);
